export function icon(name, size = 20, cls = '') {
  const d = ICONS[name] || ICONS['circle-hint'];
  return `<svg class="ic ${cls}" width="${size}" height="${size}" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">${d.map(p => `<path d="${p}"/>`).join('')}</svg>`;
}
